; ap_unit.asm - generated by make_unit.py: the autopilot of flight800_far_pm_iron.asm (verbatim) in a test harness: the host writes the inputs, sets GO and reads the results
CH          = $02FC
PORTA       = $D300
NV          = 55
VXH         = $1180
VZH         = $1200
VH          = $12C0
VFLAG       = $1400
f_alt       = $289F
f_thrust    = $2887
m061D       = $061D
m065F       = $065F
GO          = $0600                 ; 1 = run the autopilot once
OUT         = $0610                 ; results: stick, ap_l, ap_r, ap_t, ap_ph, thrust, CH

            org $2000
main        lda GO
            beq main
            jsr autopilot
            sta OUT
            lda ap_l
            sta OUT+1
            lda ap_r
            sta OUT+2
            lda ap_t
            sta OUT+3
            lda ap_ph
            sta OUT+4
            lda CH                  ; the key the autopilot pressed: applied like the game's "keys" does (ky_up / ky_dn, with ky_cancel)
            cmp #$06
            bne k_dn
            jsr ky_cancel
            lda f_thrust
            cmp #100
            bcs k_end
            inc f_thrust
            jmp k_end
k_dn        cmp #$0E
            bne k_end
            jsr ky_cancel
            lda f_thrust
            beq k_end
            dec f_thrust
k_end       lda f_thrust
            sta OUT+5
            lda CH
            sta OUT+6
            lda #$FF
            sta CH
            lda #0
            sta GO
            jmp main
ky_cancel   lda m065F
            bne kc_end
            lda #$FF
            sta m065F
            lda #$1E
            sta f_thrust
kc_end      rts

day_tick    rts
day_set     rts
ap_day      .byte 0

TRIG0       = $D010
M_FLY       = 0                     ; modes
M_FAST      = 1                     ; + a '+' key every second tick
M_SLOW      = 2                     ; + a '-' key every second tick
ALT_LO      = $19                   ; altitude band (high byte of f_alt: 64 units = 1 height unit)
ALT_HI      = $1E
WALL        = 110                   ; terrain height that counts as a wall
autopilot   lda ap_on
            bne ap_g0
            jmp ap_user
ap_g0       lda CH                  ; a key of the player
            cmp #$FF
            bne ap_x
            lda PORTA
            cmp #$FF
            bne ap_x
            lda TRIG0
            beq ap_x
            bne ap_go
ap_x        jmp ap_off
ap_go       jsr day_tick
            lda ap_t
            bne ap_run
            ldx ap_ph               ; next phase
            lda ap_len,x
            bne ap_new
            ldx #0                  ; end of the table: start again
            stx ap_ph
            lda ap_len
ap_new      sta ap_t
            inc ap_ph
ap_run      dec ap_t
            ldx ap_ph
            lda ap_mode-1,x
            beq ap_steer
            ldy CH                  ; speed up / down: a key every second tick
            cpy #$FF
            bne ap_steer
            tay
            lda ap_t
            lsr
            bcs ap_steer
            lda ap_keys-1,y
            sta CH
ap_steer    lda #0
            sta ap_l
            sta ap_r
            ldx #NV-1
ap_v        lda VFLAG,x
            and #$E0                ; outside the view or too near: ignored
            bne ap_nx
            lda VZH,x
            cmp #5
            bcc ap_nx
            cmp #40
            bcs ap_nx
            lda VH,x
            cmp #WALL
            bcc ap_nx
            ldy #1                  ; weight
            lda VXH,x
            bmi ap_neg
            cmp #5
            bcs ap_w1
            iny
ap_w1       tya
            clc
            adc ap_r
            sta ap_r
            jmp ap_nx
ap_neg      cmp #$FB
            bcc ap_w2
            iny
ap_w2       tya
            clc
            adc ap_l
            sta ap_l
ap_nx       dex
            bpl ap_v
            lda #$FF
            ldx ap_l
            cpx ap_r
            beq ap_alt
            bcs ap_goR              ; more wall on the left: bank right
            and #$FB                ; more wall on the right: bank left
            jmp ap_alt
ap_goR      and #$F7
ap_alt      ldx f_alt+1
            cpx #ALT_LO
            bcs ap_a1
            and #$FD                ; climb
ap_a1       cpx #ALT_HI+1
            bcc ap_a2
            and #$FE                ; dive
ap_a2       ldx m061D
            cpx #20
            bcs ap_ret
            and #$FD                ; too near the ground: climb, no dive
            ora #$01
ap_ret      rts
ap_off      lda #0
            sta ap_on
            tax                     ; the player flies: back to the day colours
            stx ap_day
            jsr day_set
ap_user     lda PORTA
            rts

; phase table: mode, ticks. Ends with a 0 length.
ap_mode     .byte M_FLY, M_FAST, M_FLY, M_SLOW
ap_len      .byte 250,40,250,40,0
ap_keys     .byte $06,$0E           ; '+', '-'
ap_on       .byte 1
ap_ph       .byte 0
ap_t        .byte 0
ap_l        .byte 0
ap_r        .byte 0
ap_stick    .byte $FF

            run main
